pub fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // We must return a non-empty Vec<String> for each input element.
            // Behavior may depend on keepends, but only the two length properties matter.
            let mut parts: Vec<String> = if keepends {
                // Keep line endings by splitting inclusively on '\n'.
                // Note: split_inclusive is stable and keeps the delimiter in each piece.
                s.split_inclusive('\n').map(|p| p.to_string()).collect()
            } else {
                // Drop line endings by splitting on '\n'.
                s.split('\n').map(|p| p.to_string()).collect()
            };

            // Ensure the inner list is non-empty even when the split yields nothing
            // (e.g., empty string with split_inclusive, or other edge cases).
            if parts.is_empty() {
                parts.push(s);
            }

            parts
        })
        .collect()
}